/**
 * Bounded settlement residual summary tied to one payment claim. It exposes only stable IDs, direction, amount, currency, policy, status, and lifecycle timestamps, and excludes payment details, proof/file/storage internals, auth/session data, raw request bodies, audit metadata, bill merchant/item details, OCR text, and unrelated users.
 */
export interface SettlementPaymentResidualResponse {
  id: string;
  settlementPaymentId: string;
  settlementRequestId: string;
  direction: SettlementResidualDirection;
  /**
   * Positive decimal-safe residual amount represented as a string.
   */
  amount: string;
  currency: CurrencyCode;
  policy: SettlementResidualPolicy;
  status: SettlementResidualStatus;
  createdAtUtc: string;
  resolvedAtUtc?: string | null;
}

/**
 * Bounded settlement payment response for payment read, claim, confirmation, dispute, and cancellation surfaces. It exposes payment fields, bounded allocation summaries, bounded residual summaries, and resulting settlement request status only, and excludes payment details, payment handles, payment notes, QR data, proof/file/storage internals, auth/session/credential/token data, raw request bodies, bill merchant/item details, OCR text, and unrelated users.
 */
export interface SettlementPaymentResponse {
  paymentId: string;
  settlementRequestId: string;
  paidByUserProfileId: string;
  receivedByUserProfileId: string;
  /**
   * Decimal-safe payment amount represented as a string.
   */
  amount: string;
  currency: CurrencyCode;
  status: SettlementPaymentStatus;
  paymentDate: string;
  claimedAtUtc: string;
  createdAtUtc: string;
  updatedAtUtc: string;
  allocations: SettlementPaymentAllocationResponse[];
  residuals: SettlementPaymentResidualResponse[];
  settlementRequestStatus: SettlementRequestStatus;
}

/**
 * Safe settlement payment proof metadata list. It excludes proof bytes, storage object keys, storage paths, provider URLs, direct URLs, vault references, original filenames, auth/session data, payment handles, payment notes, bill merchant/item details, raw audit metadata, and unrelated users.
 */
export interface SettlementPaymentProofListResponse {
  proofs: SettlementPaymentProofResponse[];
}

/**
 * Safe settlement payment proof file metadata. It exposes stable file and payment IDs plus content metadata only, and never contains storage object keys, storage paths, provider URLs, direct URLs, vault references, original filenames, bytes, thumbnails, OCR text, or raw audit metadata.
 */
export interface SettlementPaymentProofResponse {
  /**
   * Stable file metadata identifier for the proof attachment.
   */
  fileId: string;
  /**
   * Settlement payment claim ID that owns this proof association.
   */
  settlementPaymentId: string;
  contentType: "image/png" | "image/jpeg" | "image/webp" | "application/pdf";
  sizeBytes: number;
  /**
   * Timestamp when the proof association was created.
   */
  uploadedAtUtc: string;
  /**
   * Timestamp when the underlying file metadata was last updated.
   */
  updatedAtUtc: string;
}

/**
 * Multipart form used to upload one settlement payment proof file. The filename is treated as submitted transport metadata only and is not persisted into proof responses or audit metadata.
 */
export interface AttachSettlementPaymentProofRequest {
  /**
   * Settlement proof file. Allowed content types are image/png, image/jpeg, image/webp, and application/pdf; the maximum accepted file size is 5 MB.
   */
  file: Blob;
}

/**
 * Minimal group bill creation request. Creator/current actor are derived server-side; the route groupId is authoritative and clients cannot submit creator, owner, auth account, session, group override, file, or authorization identity fields.
 */
export interface CreateGroupBillRequest {
  /**
   * Optional merchant name after server-side trimming.
   */
  merchantName?: string | null;
  /**
   * Bill date as yyyy-MM-dd.
   */
  billDate: string;
  currency: CurrencyCode;
  items: CreateGroupBillItemRequest[];
  /**
   * Optional adjustments. Manual allocation is intentionally excluded from this first group bill endpoint slice.
   */
  adjustments?: CreateGroupBillAdjustmentRequest[] | null;
  /**
   * Optional payer rows. When omitted, null, or empty, the authenticated actor is the sole payer for the calculated bill total.
   */
  payers?: CreateGroupBillPayerRequest[] | null;
}

/**
 * Group bill item. Splits are required and every split userProfileId must belong to an active member of the route group.
 */
export interface CreateGroupBillItemRequest {
  /**
   * Item name after server-side trimming.
   */
  name: string;
  /**
   * Optional item note after server-side trimming.
   */
  note?: string | null;
  /**
   * Decimal-safe item amount represented as a string.
   */
  amount: string;
  currency?: CurrencyCode;
  splits: CreateGroupBillItemSplitRequest[];
}

/**
 * Group bill item split. exact_amount, percentage, ratio, and share_weight require basisValue; equal split does not.
 */
export interface CreateGroupBillItemSplitRequest {
  /**
   * User profile ID for an active member of the route group.
   */
  userProfileId: string;
  splitMethod: ExpenseBillItemSplitMethod;
  /**
   * Decimal-safe split basis represented as a string where required by splitMethod.
   */
  basisValue?: string | null;
  /**
   * Optional allocation order. When omitted, input order is used.
   */
  allocationOrder?: number;
}

/**
 * Optional group bill adjustment. Manual allocation is intentionally excluded from this first endpoint slice.
 */
export interface CreateGroupBillAdjustmentRequest {
  type: ExpenseBillAdjustmentType;
  direction: ExpenseBillAdjustmentDirection;
  allocationMethod: GroupBillAdjustmentAllocationMethod;
  /**
   * Decimal-safe adjustment amount represented as a string.
   */
  amount: string;
  currency?: CurrencyCode;
  /**
   * Optional adjustment reason note after server-side trimming.
   */
  reasonNote?: string | null;
}

/**
 * Optional group bill payer row. Every userProfileId must belong to an active member of the route group, and supplied payer totals must match the calculated bill total.
 */
export interface CreateGroupBillPayerRequest {
  /**
   * User profile ID for an active member of the route group.
   */
  userProfileId: string;
  /**
   * Decimal-safe payer amount represented as a string.
   */
  amount: string;
  currency?: CurrencyCode;
  /**
   * Optional payment method label snapshot after server-side trimming.
   */
  paymentMethodLabelSnapshot?: string | null;
}

/**
 * Group bills visible to the authenticated active group member. This first foundation response is intentionally unpaginated.
 */
export interface GroupBillListResponse {
  bills: GroupBillResponse[];
}

/**
 * Safe group bill response for the authenticated active group member. It excludes auth/session/credential data, group membership internals beyond submitted bill participants, storage paths, object keys, provider internals, audit metadata, OCR data, and unrelated user data. Adjustment allocations are calculated response data because no adjustment-allocation persistence table exists in the current schema.
 */
export interface GroupBillResponse {
  id: string;
  groupId: string;
  merchantName: string | null;
  billDate: string;
  status: ExpenseBillStatus;
  /**
   * Decimal-safe total amount represented as a string.
   */
  totalAmount: string;
  totalCurrency: CurrencyCode;
  createdAtUtc: string;
  updatedAtUtc: string;
  items: GroupBillItemResponse[];
  participants: GroupBillParticipantResponse[];
  payers: GroupBillPayerResponse[];
  adjustments: GroupBillAdjustmentResponse[];
  /**
   * Calculated adjustment allocation data returned for display/auditability. It is not backed by a dedicated persistence table in this schema slice.
   */
  calculatedAdjustmentAllocations: GroupBillCalculatedAdjustmentAllocationResponse[];
}

export interface GroupBillItemResponse {
  id: string;
  name: string;
  note: string | null;
  amount: string;
  currency: CurrencyCode;
  sortOrder: number;
  splits: GroupBillItemSplitResponse[];
}

export interface GroupBillItemSplitResponse {
  userProfileId: string;
  splitMethod: ExpenseBillItemSplitMethod;
  basisValue: string | null;
  resolvedAmount: string;
  resolvedCurrency: CurrencyCode;
  allocationOrder: number;
  receivedResidualMinorUnit: boolean;
}

export interface GroupBillParticipantResponse {
  userProfileId: string;
  status: ExpenseBillParticipantStatus;
  resolvedShareAmount: string;
  resolvedShareCurrency: CurrencyCode;
  /**
   * Bounded rejection reason code when the participant rejected the bill; null otherwise.
   */
  rejectionReasonCode: ExpenseBillParticipantRejectionReasonCode | null;
}

export interface GroupBillPayerResponse {
  userProfileId: string;
  amount: string;
  currency: CurrencyCode;
  paymentMethodLabelSnapshot: string | null;
}

export interface GroupBillAdjustmentResponse {
  id: string;
  type: ExpenseBillAdjustmentType;
  direction: ExpenseBillAdjustmentDirection;
  allocationMethod: GroupBillAdjustmentAllocationMethod;
  amount: string;
  currency: CurrencyCode;
  reasonNote: string | null;
  sortOrder: number;
}

export interface GroupBillCalculatedAdjustmentAllocationResponse {
  expenseBillAdjustmentId: string;
  userProfileId: string;
  direction: ExpenseBillAdjustmentDirection;
  allocationMethod: GroupBillAdjustmentAllocationMethod;
  allocatedAmount: string;
  currency: CurrencyCode;
  allocationOrder: number;
  receivedResidualMinorUnit: boolean;
}

/**
 * Expense bill root status.
 */
export type ExpenseBillStatus = "draft" | "pending_confirmation" | "confirmed" | "rejected" | "cancelled" | "finalized" | "archived";

/**
 * Expense bill participant status.
 */
export type ExpenseBillParticipantStatus = "pending_acceptance" | "accepted" | "rejected" | "partially_settled" | "settled" | "waived" | "claimed_paid" | "confirmed_paid";

/**
 * Bill revision proposal lifecycle status.
 */
export type ExpenseBillRevisionStatus = "draft_revision" | "submitted_for_review" | "withdrawn_by_proposer" | "superseded_by_resubmission" | "rejected" | "accepted_applied" | "cancelled_by_authorized_editor";

/**
 * Bill revision approval status.
 */
export type ExpenseBillRevisionApprovalStatus = "pending_review" | "approved" | "rejected" | "invalidated_by_supersession";

/**
 * Payer confirmation status for original bill payer facts and proposed revision payer facts.
 */
export type ExpenseBillPayerConfirmationStatus = "pending_confirmation" | "confirmed" | "rejected";

/**
 * Bounded participant rejection reason code.
 */
export type ExpenseBillParticipantRejectionReasonCode = "wrong_amount" | "wrong_items" | "wrong_split" | "duplicate" | "not_mine" | "other";

/**
 * Expense bill item split method.
 */
export type ExpenseBillItemSplitMethod = "equal" | "exact_amount" | "percentage" | "ratio" | "share_weight";

/**
 * Expense bill adjustment type.
 */
export type ExpenseBillAdjustmentType = "tax" | "service_charge" | "discount" | "manual_adjustment" | "credit";

/**
 * Expense bill adjustment direction.
 */
export type ExpenseBillAdjustmentDirection = "charge" | "credit";

/**
 * Supported adjustment allocation methods for the first personal bill endpoint slice.
 */
export type PersonalBillAdjustmentAllocationMethod = "equal" | "proportional_by_item_subtotal";

/**
 * Supported non-manual adjustment allocation methods for the first group bill endpoint slice.
 */
export type GroupBillAdjustmentAllocationMethod = "equal" | "proportional_by_item_subtotal";

/**
 * Settlement request status returned by settlement request surfaces.
 */
export type SettlementRequestStatus = "requested" | "partially_paid" | "marked_paid" | "confirmed" | "disputed" | "cancelled";

/**
 * Settlement request-line status returned by settlement request surfaces.
 */
export type SettlementRequestLineStatus = "open" | "partially_cleared" | "cleared" | "waived" | "disputed" | "cancelled";

/**
 * Direction of a settlement balance projection from the authenticated actor's perspective.
 */
export type SettlementBalanceDirection = "incoming" | "outgoing";

/**
 * Supported settlement basket selection mode for the first preview and create slices.
 */
export type SettlementBasketSelectionMode = "pay_all_outstanding_for_counterparty";

/**
 * Settlement payment status returned by settlement payment surfaces. Day 1 payment claim creates marked_paid payments, receiver confirmation moves them to confirmed, receiver dispute moves eligible marked_paid claims to disputed, and debtor cancellation moves eligible own marked_paid claims to cancelled.
 */
export type SettlementPaymentStatus = "marked_paid" | "confirmed" | "disputed" | "cancelled";

/**
 * Direction of a proposed settlement residual relative to the exact selected outstanding total.
 */
export type SettlementResidualDirection = "underpayment" | "overpayment";

/**
 * Supported residual policy values for explicit payment-claim-time residual proposals.
 */
export type SettlementResidualPolicy = "remaining_balance" | "carried_forward" | "waived" | "credit_forward" | "waived_by_payer" | "applied_to_other_line";

/**
 * Settlement residual status returned by payment response summaries. Payment claims create pending residuals, receiver residual confirmation moves supported pending residuals to policy-derived confirmed, carried_forward, waived, or credited statuses, and dispute/cancellation neutralizes pending residuals to disputed or cancelled.
 */
export type SettlementResidualStatus = "pending_receiver_confirmation" | "confirmed" | "carried_forward" | "waived" | "credited" | "disputed" | "cancelled";

/**
 * Payment details visibility policy value. The default app behavior is settlement_counterparties_only.
 */
export type PaymentDetailsVisibility = "private" | "settlement_counterparties_only" | "group_members_when_shared";

/**
 * Safe self payment-details response for the authenticated actor. It excludes auth account IDs, session IDs, credential state, audit metadata, counterparty data, storage object keys, storage paths, provider URLs, vault internals, and submitted filenames.
 */
export interface SelfPaymentDetailsResponse {
  /**
   * True only when an active payment profile row exists for the authenticated actor.
   */
  isConfigured: boolean;
  id: string | null;
  preferredMethodLabel: string | null;
  paymentHandle: string | null;
  paymentNote: string | null;
  visibility: PaymentDetailsVisibility;
  /**
   * Safe metadata for the active linked payment QR file, or null when no active QR is linked.
   */
  qrFile: SelfPaymentDetailsQrFileResponse | null;
  createdAtUtc: string | null;
  updatedAtUtc: string | null;
}

/**
 * Safe self payment QR file metadata. It never contains storage object keys, storage paths, provider URLs, vault references, bytes, thumbnails, direct URLs, or submitted filenames.
 */
export interface SelfPaymentDetailsQrFileResponse {
  /**
   * Stable file metadata identifier for the linked QR file.
   */
  id: string;
  contentType: "image/png" | "image/jpeg" | "image/webp";
  sizeBytes: number;
  updatedAtUtc: string;
}

/**
 * Safe settlement-scoped counterparty payment-details response. It is not the self owner response and excludes payment profile IDs, owner-only timestamps, auth/session/credential data, audit internals, storage object keys, storage paths, provider URLs, vault internals, QR bytes, direct URLs, filenames, and unrelated users.
 */
export interface SettlementCounterpartyPaymentDetailsResponse {
  /**
   * Target counterparty user profile ID proven through the settlement request relationship.
   */
  userProfileId: string;
  /**
   * True only when an active target payment profile is visible through the settlement counterparty relationship.
   */
  isConfigured: boolean;
  /**
   * Visibility-scoped payment method label, or null when not configured or not visible.
   */
  preferredMethodLabel: string | null;
  /**
   * Visibility-scoped payment handle, or null when not configured or not visible.
   */
  paymentHandle: string | null;
  /**
   * Visibility-scoped payment note, or null when not configured or not visible.
   */
  paymentNote: string | null;
  visibilityApplied: PaymentDetailsVisibility;
  /**
   * Safe metadata for the active linked payment QR file when visible through the settlement counterparty relationship, or null.
   */
  qrFile: SettlementCounterpartyPaymentDetailsQrFileResponse | null;
}

/**
 * Safe counterparty payment QR file metadata for a settlement-scoped relationship. It never contains storage object keys, storage paths, provider URLs, vault references, bytes, thumbnails, direct URLs, or submitted filenames.
 */
export interface SettlementCounterpartyPaymentDetailsQrFileResponse {
  /**
   * Stable file metadata identifier for the linked QR file.
   */
  id: string;
  contentType: "image/png" | "image/jpeg" | "image/webp";
  sizeBytes: number;
  updatedAtUtc: string;
}

/**
 * Multipart form used to upload a single self payment QR image. The filename is treated as submitted transport metadata only and is not returned by the API.
 */
export interface AttachSelfPaymentQrRequest {
  /**
   * Payment QR image. Allowed content types are image/png, image/jpeg, and image/webp; the maximum accepted file size is 2 MB.
   */
  file: Blob;
}

/**
 * Safe self payment-details update. Missing text fields are preserved on update, explicit null clears them, whitespace-only text normalizes to null, and omitted visibility defaults only when creating a new payment profile.
 */
export interface UpdateSelfPaymentDetailsRequest {
  /**
   * Optional payment method label after server-side trimming.
   */
  preferredMethodLabel?: string | null;
  /**
   * Optional user-entered payment handle after server-side trimming.
   */
  paymentHandle?: string | null;
  /**
   * Optional user-entered payment note after server-side trimming.
   */
  paymentNote?: string | null;
  visibility?: PaymentDetailsVisibility;
}

/**
 * Safe self-profile response for the authenticated actor.
 */
export interface SelfUserProfileResponse {
  id: string;
  displayName: string;
  defaultCurrency: CurrencyCode | null;
  createdAtUtc: string;
  updatedAtUtc: string;
}

/**
 * Safe self-profile update. Profile identity is derived from the authenticated actor, not from client input.
 */
export interface UpdateSelfUserProfileRequest {
  /**
   * Display name after server-side trimming. Blank or whitespace-only values are rejected.
   */
  displayName?: string;
  /**
   * Optional default currency. Explicit null clears the value.
   */
  defaultCurrency?: CurrencyCode | null;
}

/**
 * Safe active session metadata for the authenticated account. The list is capped by the API.
 */
export interface SessionListResponse {
  sessions: SessionSummary[];
}

/**
 * Bounded session metadata that excludes token material, hashes, network data, user-agent data, and revocation details.
 */
export interface SessionSummary {
  id: string;
  isCurrent: boolean;
  status: "active";
  issuedAtUtc: string;
  expiresAtUtc: string;
  lastSeenAtUtc: string | null;
  deviceLabel: string | null;
}

/**
 * ISO-4217 style currency code.
 */
export type CurrencyCode = string;

/**
 * Decimal-safe money value with an attached currency.
 */
export interface Money {
  /**
   * Decimal-safe amount represented as a string to avoid floating point loss.
   */
  amount: string;
  currency: CurrencyCode;
}

/**
 * Placeholder rounding modes for future policy-driven money handling.
 */
export type RoundingMode = "up" | "down" | "nearest" | "bankers";

/**
 * Placeholder sync state values shared by local and server-mode clients.
 */
export type SyncState = "queued" | "synced" | "conflict" | "failed";

/**
 * Stable storage object reference that does not expose physical filesystem paths.
 */
export interface StorageObjectRef {
  /**
   * Opaque storage object identifier.
   */
  id: string;
  contentType?: string;
  sizeBytes?: number;
}

/**
 * RFC 7807 / RFC 9457 style problem response.
 */
export interface ProblemDetails {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
}

/**
 * Placeholder OCR job status values for future worker contract design.
 */
export type OcrJobStatus = "queued" | "processing" | "completed" | "failed";

export interface GetHealthResponse {
  status: string;
}

export interface GetHealthReadyResponse {
  status: "ready";
  service: string;
  checks: { postgres: "ok"; rabbitmq: "ok"; storage: "ok" };
}
